[
  {
    "question": "In DBMS terminology, what is the difference between a schema and an instance?",
    "options": {
      "A": "A schema defines the logical structure of the database, while an instance is the actual data stored at a point in time.",
      "B": "A schema is the current data, and an instance is the set of tables and columns.",
      "C": "A schema describes physical storage details, whereas an instance describes user views.",
      "D": "A schema is the DBMS software, and an instance is the hardware it runs on."
    },
    "correct_answer": "A",
    "explanation": "The schema is the blueprint (tables, columns, constraints) and remains relatively stable; an instance is the collection of tuples that populate those tables at a given moment.",
    "difficulty": "Medium"
  },
  {
    "question": "What does the term \"tuple\" refer to in the relational model?",
    "options": {
      "A": "A single row of a relation.",
      "B": "A column (attribute) of a relation.",
      "C": "The set of all possible values for an attribute.",
      "D": "A foreign key reference."
    },
    "correct_answer": "A",
    "explanation": "A tuple is the ordered set of attribute values that makes up one row in a relational table.",
    "difficulty": "Medium"
  },
  {
    "question": "Which relational‑algebra operation corresponds most closely to the SQL clause SELECT DISTINCT?",
    "options": {
      "A": "Projection",
      "B": "Selection",
      "C": "Union",
      "D": "Difference"
    },
    "correct_answer": "A",
    "explanation": "Projection returns specified columns and eliminates duplicate rows, matching the effect of SELECT DISTINCT.",
    "difficulty": "Medium"
  },
  {
    "question": "Physical data independence means that:",
    "options": {
      "A": "Changes to internal storage structures do not affect the conceptual schema.",
      "B": "Changes to the conceptual schema do not affect external user views.",
      "C": "Changes to external views do not affect the logical schema.",
      "D": "Changes to query syntax do not affect stored data."
    },
    "correct_answer": "A",
    "explanation": "Physical data independence protects the higher‑level schema from modifications in how data is actually stored on disk.",
    "difficulty": "Medium"
  },
  {
    "question": "What is the primary purpose of a primary key in a relational table?",
    "options": {
      "A": "To uniquely identify each tuple in the table.",
      "B": "To enforce referential integrity with other tables.",
      "C": "To allow duplicate rows for faster inserts.",
      "D": "To store large binary objects."
    },
    "correct_answer": "A",
    "explanation": "A primary key must contain a unique, non‑null value for every row, providing a reliable identifier for each tuple.",
    "difficulty": "Medium"
  }
]
